<script setup lang="ts">
import { formatDemoTime } from '~/domain/selectors'
definePageMeta({ layout: 'workspace' })
useHead({ title: 'Moderasi - UKIN PPG UNJ' })
const u = useUkin(), route = useRoute(), { error, message, act } = useOperationFeedback()
const id = ref(typeof route.query.id === 'string' ? route.query.id : ''), reason = ref(''), confirmed = ref(false)
const cases = computed(() => u.user.value && u.user.value.role !== 'peserta' ? u.operations.listModerations() : [])
const selected = computed(() => { if (!id.value) return null; try { return u.operations.getModeration(id.value) } catch { return null } })
const own = computed(() => selected.value?.comparisons.find(c => c.own))
const open = computed(() => selected.value && ['open', 'awaiting_responses'].includes(selected.value.status))
watch(id, () => { reason.value = ''; confirmed.value = false })
function respond(decision: 'retain' | 'revise') { if (!own.value) return; act(() => { if (!confirmed.value) throw new Error('Konfirmasi tanggapan diperlukan.'); u.operations.respondModeration(id.value, decision, own.value!.finalId, reason.value); confirmed.value = false; reason.value = '' }, 'Tanggapan Anda tersimpan pada versi final ini.') }
function close() { act(() => { u.operations.closeModeration(id.value, reason.value, confirmed.value); reason.value = ''; confirmed.value = false }, 'Kasus ditutup dengan catatan. Skor masing-masing penguji tetap independen.') }
</script>
<template>
  <div class="operations-page"><header><p class="eyebrow">RUANG MODERASI</p><h1>Bandingkan bukti, jelaskan keputusan.</h1><p class="muted">Perbandingan terbatas pada indikator yang dipilih pengelola. Draf dan catatan indikator lain tetap pribadi.</p></header>
    <section class="op-hero"><div><h2>{{ cases.filter(c => ['open', 'awaiting_responses'].includes(c.status)).length }} kasus menunggu tindak lanjut</h2><p class="op-caption">Tidak ada deteksi selisih otomatis. Pengelola menutup kasus setelah kedua penguji menanggapi final terkini; skor tidak harus sama.</p></div><AppIcon name="shield" :size="48" /></section>
    <NuxtLink v-if="u.user.value?.role === 'pengelola'" to="/app/publikasi">Buka kasus dari antrean dua penilaian final</NuxtLink>
    <label class="op-field">Kasus moderasi<select v-model="id"><option value="">Pilih kasus</option><option v-for="c in cases" :key="c.id" :value="c.id">{{ c.participant }} / {{ c.status }}{{ c.fixture ? ' / Contoh' : '' }}</option></select></label>
    <p v-if="error" class="op-error" role="alert">{{ error }}</p><p v-if="message" class="op-success" role="status">{{ message }}</p>
    <section v-if="selected" class="op-panel"><div class="op-row"><div><h2>{{ selected.participant }}</h2><p class="op-caption">{{ selected.rubricVersionId }} / {{ formatDemoTime(selected.openedAt) }}</p></div><span class="op-tag">{{ selected.status }}</span></div><p class="op-note op-warning">{{ selected.reason }}</p><NuxtLink :to="{ path: '/app/bukti', query: { id: selected.evidenceVersionId } }">Periksa snapshot bukti yang dimoderasi</NuxtLink>
      <div class="op-comparison"><article v-for="c in selected.comparisons" :key="c.assignmentId" :class="{ 'op-own': c.own }"><p class="eyebrow">{{ c.kind }}{{ c.own ? ' / Penilaian Anda' : '' }}</p><h3>{{ c.name }}</h3><p class="op-caption">Final v{{ c.finalVersion }}{{ c.hasDraft ? ' / Revisi sedang dikerjakan' : '' }}</p><section v-for="i in c.indicators" :key="i.id" class="op-divider"><p class="op-caption">{{ i.component }} / {{ i.id }}</p><h3>{{ i.title }}</h3><strong class="op-score">{{ i.score }}<small style="font-size:14px"> / 4</small></strong><p class="op-note">{{ i.note || 'Tanpa catatan indikator.' }}</p><p class="op-caption">Rujukan: {{ i.evidenceId }}</p></section></article></div>
      <section class="op-summary"><h3>Tanggapan penguji</h3><p v-if="!selected.responses.length" class="op-caption">Belum ada tanggapan.</p><article v-for="r in selected.responses" :key="r.examinerId"><strong>{{ selected.comparisons.find(c => c.examinerId === r.examinerId)?.name }} / {{ r.decision === 'retain' ? 'Mempertahankan' : 'Merevisi' }}</strong><p class="op-note">{{ r.reason }}</p><small class="op-caption">{{ formatDemoTime(r.at) }}{{ selected.comparisons.some(c => c.examinerId === r.examinerId && c.finalId !== r.finalId) ? ' / Perlu tanggapan ulang: final berubah' : '' }}</small></article></section>
      <template v-if="open"><p v-if="own" class="op-warning">Revisi dilakukan di ruang penilaian pribadi, dengan alasan dan final versi baru. Setelah finalisasi, kembali ke kasus ini untuk mengirim tanggapan.</p><NuxtLink v-if="own" :to="{ path: '/app/penilaian', query: { id: own.assignmentId } }">{{ own.hasDraft ? 'Lanjutkan draf revisi Anda' : 'Buka penilaian Anda untuk revisi' }}</NuxtLink><label class="op-field">{{ own ? 'Penjelasan keputusan Anda' : 'Catatan penutupan kasus' }}<textarea v-model="reason" maxlength="5000" /></label><label class="op-check"><input v-model="confirmed" type="checkbox" />Saya telah meninjau bukti, versi final, dan tanggapan yang relevan.</label><div class="op-actions"><template v-if="own"><UButton :disabled="own.hasDraft" @click="respond('retain')">Pertahankan final awal</UButton><UButton :disabled="own.hasDraft" variant="soft" @click="respond('revise')">Catat final revisi</UButton></template><UButton v-else-if="u.user.value?.role === 'pengelola'" @click="close">Tutup kasus moderasi</UButton></div></template>
      <div v-else class="op-summary"><h3>{{ selected.status === 'archived' ? 'Alasan pengarsipan' : 'Catatan penutupan' }}</h3><p class="op-note">{{ selected.resolution }}</p><p v-if="selected.closedAt" class="op-caption">{{ formatDemoTime(selected.closedAt) }}</p></div>
    </section><p v-else class="op-empty">{{ cases.length ? 'Pilih kasus untuk memeriksa indikator dan tanggapan.' : 'Belum ada kasus moderasi untuk akun ini.' }}</p>
  </div>
</template>
